export function mountMontage({root,button,sprite,replay,reduced=false,onClose=()=>{}}){let started=0,frame=0,active=false;const scenes=[{kicker:'TWELVE FIGHTERS',title:'PICK YOUR CHAOS.',detail:'Atomic dogs. Fire swords. Unicorn armies.',types:[5,9,7]},{kicker:'SEVEN WORLDS',title:'TAKE THE HIGH GROUND.',detail:'Cloud islands. Neon rooftops. Ocean rafts.',types:[3,4,8]},{kicker:'ONE LAST STICK',title:'SMASH. SURVIVE. REPEAT.',detail:'Bring your friends. Leave with the trophy.',types:[10,11,6]}];
 const close=()=>{if(!active)return;active=false;root.hidden=true;cancelAnimationFrame(frame);onClose();};
 const paint=now=>{if(!active)return;const elapsed=now-started;if(elapsed>=9600){close();return;}const index=Math.min(2,Math.floor(elapsed/3200));if(root.dataset.scene!==String(index)){const s=scenes[index];root.dataset.scene=String(index);root.querySelector('[data-montage-kicker]').textContent=s.kicker;root.querySelector('[data-montage-title]').textContent=s.title;root.querySelector('[data-montage-detail]').textContent=s.detail;root.querySelector('[data-montage-cast]').innerHTML=s.types.map((type,i)=>`<div class="montage-fighter fighter-${i}">${sprite(type)}</div>`).join('');}root.style.setProperty('--progress',`${elapsed/9600*100}%`);frame=requestAnimationFrame(paint);};
 const open=()=>{active=true;root.hidden=false;root.dataset.scene='';started=performance.now();frame=requestAnimationFrame(paint);};
 button.onclick=close;replay.onclick=open;window.addEventListener('keydown',e=>{if(active&&e.code==='Space'){e.preventDefault();e.stopImmediatePropagation();close();}},true);if(!reduced)open();return {open,close,get active(){return active}};}
